// Generates apps/web/src/api/generated.ts from contracts/*.v0.1.json.
//
// contracts/ is the source of truth for API paths, methods and wire types. The
// web app must not restate them by hand. Output is stable: running this twice
// produces byte-identical files. Do not edit the generated file by hand.
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const contractsDir = join(root, 'contracts');
const outFile = join(root, 'apps/web/src/api/generated.ts');

const contractFiles = readdirSync(contractsDir).filter((f) => f.endsWith('.v0.1.json')).sort();

// Older contracts (auth-membership, development-transactions) predate the
// operations/schemaDefinitions shape and describe no callable endpoints.
const contracts = [];
for (const file of contractFiles) {
  const data = JSON.parse(readFileSync(join(contractsDir, file), 'utf8'));
  if (!Array.isArray(data.operations) || !data.schemaDefinitions) continue;
  contracts.push({ slug: file.replace(/\.v0\.1\.json$/, ''), data });
}

const camel = (slug) => slug.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const pascal = (value) => value.charAt(0).toUpperCase() + value.slice(1);

// A definition name reused across contracts is emitted once when the bodies
// match; otherwise each contract gets its own prefixed type so a ref never
// points at another contract's shape.
const definitionBodies = new Map();
for (const c of contracts) for (const [name, schema] of Object.entries(c.data.schemaDefinitions)) {
  const body = JSON.stringify(schema);
  if (!definitionBodies.has(name)) definitionBodies.set(name, new Set());
  definitionBodies.get(name).add(body);
}
const sharedName = (name) => definitionBodies.get(name).size === 1;
const definitionName = (slug, name) => (sharedName(name) ? name : camel(slug) + name);

const refName = (c, ref) => {
  const prefix = '#/definitions/';
  if (!ref.startsWith(prefix)) throw new Error(`${c.slug}: unsupported ref ${ref}`);
  const name = ref.slice(prefix.length);
  if (!c.data.schemaDefinitions[name]) throw new Error(`${c.slug}: missing definition ${name}`);
  return definitionName(c.slug, name);
};

const render = (schema, c, indent) => {
  if (schema.$ref) return refName(c, schema.$ref);
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (schema.enum) return [...new Set(schema.enum.map((v) => JSON.stringify(v)))].join(' | ');
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  if (types.length === 1) return renderSingle(types[0], schema, c, indent);
  return types.map((t) => renderSingle(t, schema, c, indent)).join(' | ');
};

const renderSingle = (type, schema, c, indent) => {
  switch (type) {
    case 'string': return 'string';
    case 'integer':
    case 'number': return 'number';
    case 'boolean': return 'boolean';
    case 'null': return 'null';
    case 'array': return arrayOf(schema.items, c, indent);
    case 'object': return objectLiteral(schema, c, indent);
    default: throw new Error(`${c.slug}: unsupported schema type ${String(type)}`);
  }
};

const arrayOf = (items, c, indent) => {
  if (!items) throw new Error(`${c.slug}: array without items`);
  const inner = render(items, c, indent);
  return inner.includes(' | ') || inner.includes('\n') ? `(${inner})[]` : `${inner}[]`;
};

const propertyKey = (key) => (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key));

const objectLiteral = (schema, c, indent) => {
  const properties = Object.entries(schema.properties ?? {});
  if (properties.length === 0) return 'Record<string, unknown>';
  const required = new Set(schema.required ?? []);
  const pad = ' '.repeat(indent + 2);
  const lines = properties.map(([key, value]) =>
    `${pad}${propertyKey(key)}${required.has(key) ? '' : '?'}: ${render(value, c, indent + 2)};`);
  return `{\n${lines.join('\n')}\n${' '.repeat(indent)}}`;
};

// Type aliases (not interfaces) so object shapes stay assignable to the
// Record parameters used by operationPath/queryString.
const emitType = (name, schema, c) => `export type ${name} = ${render(schema, c, 0)};`;

const successStatuses = (operation) => Object.keys(operation.responses).map(Number).filter((s) => s >= 200 && s < 300).sort((a, b) => a - b);

const lines = [];
const push = (line = '') => lines.push(line);

push('// Generated by scripts/generate-client.mjs from contracts/*.v0.1.json. Do not edit.');
push('// Paths, methods and wire types come from the contracts; nothing here is hand-tuned.');
push('');
push("export type HttpMethod = 'DELETE' | 'GET' | 'PATCH' | 'POST' | 'PUT';");
push('export type ApiCall = (path: string, method: HttpMethod, body?: unknown) => Promise<unknown>;');
push('');
push('// Uniform error envelope: HTTP status decides failure, code decides meaning.');
push('export interface ApiErrorResponse {');
push('  error: { code: string; message?: string };');
push('}');
push('');

const operations = contracts.flatMap((c) => c.data.operations.map((operation) => ({ c, operation })))
  .sort((a, b) => a.operation.id.localeCompare(b.operation.id));

push('export const operations = {');
for (const { operation } of operations) {
  push(`  ${operation.id}: { method: ${JSON.stringify(operation.method)}, path: ${JSON.stringify(operation.path)}, authentication: ${JSON.stringify(operation.authentication)} },`);
}
push('} as const;');
push('export type OperationId = keyof typeof operations;');
push('');
push('export function operationPath(id: OperationId, params: Record<string, string> = {}): string {');
push('  return operations[id].path.replace(/:([A-Za-z]+)/g, (_, key: string) => encodeURIComponent(params[key]!));');
push('}');
push('');
push('export function queryString(query: Record<string, string | number | boolean | undefined>): string {');
push('  const search = new URLSearchParams();');
push('  for (const [key, value] of Object.entries(query)) if (value !== undefined) search.set(key, String(value));');
push("  return search.toString() ? '?' + search.toString() : '';");
push('}');
push('');

// definition types, then per-operation request/response/params/query types
const emittedDefinitions = new Set();
for (const c of contracts) {
  const names = Object.keys(c.data.schemaDefinitions).sort();
  const block = [];
  for (const name of names) {
    const typeName = definitionName(c.slug, name);
    if (emittedDefinitions.has(typeName)) continue;
    emittedDefinitions.add(typeName);
    block.push(emitType(typeName, c.data.schemaDefinitions[name], c));
  }
  if (block.length === 0) continue;
  push(`// contracts/${c.slug}.v0.1.json — schemaDefinitions`);
  for (const blockLine of block) push(blockLine);
  push('');
}

const operationTypes = [];
const wrappers = [];
for (const { c, operation } of operations) {
  const base = pascal(operation.id);
  const types = [];
  if (operation.paramsSchema) types.push({ name: `${base}PathParams`, schema: operation.paramsSchema });
  if (operation.requestSchema) types.push({ name: `${base}Request`, schema: operation.requestSchema });
  const statuses = successStatuses(operation);
  if (statuses.length === 0) throw new Error(`${c.slug}/${operation.id}: no success response`);
  for (const status of statuses) types.push({ name: `${base}Response${status}`, schema: operation.responses[String(status)] });
  if (operation.querySchema) types.push({ name: `${base}Query`, schema: operation.querySchema });
  for (const type of types) operationTypes.push(emitType(type.name, type.schema, c));

  const responseType = statuses.length === 1 ? `${base}Response${statuses[0]}` : statuses.map((s) => `${base}Response${s}`).join(' | ');
  const signature = ['  call: ApiCall,'];
  const args = [];
  if (operation.paramsSchema) { signature.push(`  params: ${base}PathParams,`); args.push(`operationPath('${operation.id}', params)`); }
  else args.push(`operationPath('${operation.id}')`);
  if (operation.requestSchema) { signature.push(`  body: ${base}Request,`); }
  if (operation.querySchema) {
    const optional = (operation.querySchema.required ?? []).length === 0;
    signature.push(`  query${optional ? '?' : ''}: ${base}Query,`);
    args[0] = `${args[0]} + queryString(query ?? {})`;
  }
  const callArgs = [...args, JSON.stringify(operation.method)];
  if (operation.requestSchema) callArgs.push('body');
  wrappers.push([
    `export async function ${operation.id}(`,
    ...signature,
    `): Promise<${responseType}> {`,
    `  return await call(${callArgs.join(', ')}) as ${responseType};`,
    '}',
    '',
  ].join('\n'));
}

push('// Operation wire types, generated from each operation\'s schema.');
for (const type of operationTypes) push(type);
push('');
push('// Thin callers: transport, auth and runtime validation stay with the client.');
for (const wrapper of wrappers) push(wrapper);

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, lines.join('\n').replace(/\n+$/, '\n'));
console.log(`generated ${operations.length} operations from ${contracts.length} contracts -> ${outFile}`);
